import json
from fractions import Fraction
from math import sqrt

mags = [1, 2, 3]
pairs = [(0, 1), (1, 2), (0, 2)]

# In a plane, three vectors with equal pairwise angles t:
# either t = 0 (all same direction), or 3t = 360 so t = 120 degrees.
cases = {"0deg": Fraction(1), "120deg": Fraction(-1, 2)}

results = {}
for name, cosv in cases.items():
    sq = sum(Fraction(m * m) for m in mags)
    sq += sum(2 * mags[i] * mags[j] * cosv for i, j in pairs)
    results[name] = sq

# Verify by explicit coordinates
import math
def check(angles_deg):
    x = sum(m * math.cos(math.radians(a)) for m, a in zip(mags, angles_deg))
    y = sum(m * math.sin(math.radians(a)) for m, a in zip(mags, angles_deg))
    return math.hypot(x, y)

num0 = check([0, 0, 0])
num120 = check([0, 120, 240])

answers = []
for name, sq in results.items():
    if sq.denominator == 1 and int(sqrt(sq.numerator)) ** 2 == sq.numerator:
        answers.append(str(int(sqrt(sq.numerator))))
    else:
        answers.append("sqrt(%s)" % sq)

print(json.dumps({
    "final_answer": " or ".join(answers),
    "evidence": {
        "squared_magnitudes": {k: str(v) for k, v in results.items()},
        "numeric_check": {"0deg": num0, "120deg": num120},
    },
}))
